      # ─── Verzeichnisse (State + Metadata) ─────────────────────────────
      systemd.tmpfiles.rules = [
        "d '${stateDir}'            0755 jellyfin media -"
        "d '${metadataDir}'         0775 jellyfin media -"
        "d '${jellyfinMetadataDir}' 0775 jellyfin media -"
      ];

      # ─── Systemd-Service (explizit, keine Magie) ──────────────────────
      systemd.services.jellyfin = {
        description = "Jellyfin Media Server (ID ${toString num})";
        after       = [ "network-online.target" ];
        requires    = [ "network-online.target" ];
        wantedBy    = [ "multi-user.target" ];

        # ── First-Boot-Hydration: XML-Seeds nur bei fehlender Config ────
        # Idempotent: überschreibt niemals eine bestehende User-Config.
        preStart = ''
          ${pkgs.coreutils}/bin/mkdir -p '${stateDir}/config'
          if [ ! -f '${stateDir}/config/system.xml' ]; then
            ${pkgs.coreutils}/bin/cp '${systemXmlSeed}' '${stateDir}/config/system.xml'
            ${pkgs.coreutils}/bin/chmod 0640 '${stateDir}/config/system.xml'
          fi
          if [ ! -f '${stateDir}/config/network.xml' ]; then
            ${pkgs.coreutils}/bin/cp '${networkXmlSeed}' '${stateDir}/config/network.xml'
            ${pkgs.coreutils}/bin/chmod 0640 '${stateDir}/config/network.xml'
          fi
          if [ ! -f '${stateDir}/config/branding.xml' ]; then
            ${pkgs.coreutils}/bin/cp '${brandingXmlSeed}' '${stateDir}/config/branding.xml'
            ${pkgs.coreutils}/bin/chmod 0640 '${stateDir}/config/branding.xml'
          fi
        '';

        serviceConfig = lib.mkMerge [
          # Härtungsprofil (dotnet + GPU)
          profiles.dotnet-gpu
          # RAM-Policy (OOM-Schutz, MemoryMax)
          memoryPolicy.jellyfin
          # Konkrete Service-Konfiguration
          {
            ExecStart = "${pkgs.jellyfin}/bin/jellyfin "
                      + "--datadir ${stateDir} "
                      + "--cachedir ${metadataDir} "
                      + "--webdir ${pkgs.jellyfin-web}/share/jellyfin-web";

            User  = "jellyfin";
            Group = "media";
            UMask = "0002";

            SupplementaryGroups = [ "video" "render" ];

            # DeviceAllow nur wenn ein Render-Device konfiguriert ist
            DeviceAllow = lib.mkIf (renderDevice != null) [
              "${renderDevice} rwm"
            ];

            StateDirectory     = "jellyfin-${toString port}";
            ReadWritePaths     = [ stateDir metadataDir ];
            BindReadOnlyPaths  = [ "${svc.storage.mediaRoot}:${svc.storage.mediaRoot}" ];
            InaccessiblePaths  = [ "-${svc.storage.secretsDir}" ];

            # /transcode liegt im RAM (SSD-TBW-Schonung)
            TemporaryFileSystem = "/transcode:size=4G";
            RuntimeDirectory    = "jellyfin-transcode";
          }
        ]
        # Credential nur wenn vorhanden (Assertion garantiert es, aber defensiv)
        // lib.optionalAttrs hasCred {
          LoadCredentialEncrypted = [ "${credName}:${cfg.adminPasswordCredential}" ];
        };

        # ── Umgebungsvariablen ─────────────────────────────────────────
        environment = {
          JELLYFIN_PublishedServerUrl = jellyfinUrl;
          JELLYFIN_TRANSCODE_DIR      = "/transcode";
        }
        # Admin-Passwort-Pfad nur wenn Credential gesetzt
        // lib.optionalAttrs hasCred {
          JELLYFIN_ADMIN_PASSWORD__FILE = credFile;
        }
        # GPU-Variablen nur wenn HW-Accel aktiv
        // gpuEnv;
      };

      # ─── Ingress (Caddy) — aus dem Manifest gespeist ──────────────────
      # Kein hardcoded "stream" mehr. Änderung an einer Stelle (Manifest)
      # propagiert automatisch in Caddy, mDNS und Landingpage.
      medinix.ingress.vhosts."jellyfin" = {
        inherit (meta) accessGroup;
      };

      # ─── Hardware Graphics (nur wenn Intel/VAAPI aktiv) ───────────────
      hardware.graphics = lib.mkIf (accelType == "intel" || accelType == "vaapi") {
        enable = true;
        extraPackages = with pkgs; [
          intel-media-driver
          vpl-gpu-rt
          intel-vaapi-driver
          intel-compute-runtime
        ];
      };
    })
  ];
}
```

